const svg=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const initial=()=>({version:1,records:{},bookmarks:[],read:[],session:null});
let state=initial(),storageOK=true;
try { const raw=localStorage.getItem(KEY); if(raw){const loaded=JSON.parse(raw);state=C.validImport(loaded,new Set(DATA.questions.map(q=>q.id)),new Set(DATA.topics.map(t=>t.id)));if(loaded.session&&Array.isArray(loaded.session.ids)&&loaded.session.ids.every(id=>DATA.questions.some(q=>q.id===id))&&Number.isInteger(loaded.session.index)&&loaded.session.index>=0&&loaded.session.index<=loaded.session.ids.length&&typeof loaded.session.drafts==='object'&&loaded.session.drafts)state.session=loaded.session;}} catch(e){storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;toast('Браузер не сохранил прогресс. Экспортируйте его в разделе «Мой прогресс».');}}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500);}
function link(route,params={}){const s=new URLSearchParams(Object.entries(params).filter(([,v])=>v!==undefined&&v!==''));return '#'+route+(s.size?'?'+s:'');}
function current(){const [route,...tail]=location.hash.slice(1).split('?');return {route:route||'home',p:new URLSearchParams(tail.join('?'))};}
function navigate(route,params={}){const target=link(route,params);if(location.hash===target)render();else location.hash=target;}
function sourceLink(source){if(source.url)return `<a class="source-link" href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.title)} ↗</a>${source.checked?` <small class="muted">· сверено ${esc(source.checked)}</small>`:''}`;return `<span class="source-link">↗ ${esc(source.path)} · ${source.document?'док.':'яч.'} ${source.cells.map(n=>`<a href="${esc(link('source',{path:source.path,cell:n}))}">${n}</a>`).join(', ')}</span>${(source.related||[]).map(s=>`<br>${sourceLink(s)}`).join('')}`;}
function safeHTML(html){
  const d=new DOMParser().parseFromString(html,'text/html');
  const allowed=new Set('P H1 H2 H3 H4 H5 H6 UL OL LI STRONG EM DEL BLOCKQUOTE PRE CODE A IMG TABLE THEAD TBODY TR TH TD HR BR DIV SPAN DETAILS SUMMARY SUB SUP'.split(' '));
  for(const el of [...d.body.querySelectorAll('*')]){
    if(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','SVG','MATH','FORM','INPUT','BUTTON'].includes(el.tagName)){el.remove();continue;}
    if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);continue;}
    const href=el.getAttribute('href'),src=el.getAttribute('src'),alt=el.getAttribute('alt');
    for(const attr of [...el.attributes])el.removeAttribute(attr.name);
    if(el.tagName==='A'&&href&&/^(https?:\/\/|#)/i.test(href)){el.setAttribute('href',href);if(/^https?:/.test(href)){el.target='_blank';el.rel='noopener noreferrer';}}
    if(el.tagName==='IMG'){
      if(src&&/^assets\/[a-zA-Z0-9._-]+$/.test(src)){el.src=src;el.alt=alt||'Иллюстрация из ноутбука';el.loading='lazy';}
      else el.replaceWith(d.createTextNode('[Внешняя иллюстрация не загружается в офлайн-режиме]'));
    }
  }
  return d.body.innerHTML;
}
function md(text){
  const math=[];
  const protectedText=String(text).replace(/(```[\s\S]*?```|`[^`\n]+`)|(\$\$[\s\S]*?\$\$|\\\[[\s\S]*?\\\]|\\\([\s\S]*?\\\)|\$[^$\n]+?\$)/g,(whole,code,formula)=>{
    if(code)return code;
    const display=formula.startsWith('$$')||formula.startsWith('\\[');
    const content=formula.startsWith('$')?formula.slice(display?2:1,display?-2:-1):formula.slice(2,-2);
    const token='CVFORMULAPLACEHOLDER'+math.length+'END';math.push({token,content,display});return token;
  });
  let html=safeHTML(marked.parse(protectedText));
  for(const m of math)html=html.replaceAll(m.token,katex.renderToString(m.content,{displayMode:m.display,throwOnError:false,strict:false,trust:false}));
  return html;
}
function formula(text){return text?`<div class="formula">${katex.renderToString(text,{displayMode:true,throwOnError:false,strict:false,trust:false})}</div>`:'';}
function stats(lesson){const qs=DATA.questions.filter(q=>!lesson||q.lesson===lesson), rs=qs.filter(q=>state.records[q.id]);return {total:qs.length,seen:rs.length,good:rs.filter(q=>state.records[q.id].score===1).length,errors:rs.filter(q=>state.records[q.id].score<1).length,due:rs.filter(q=>state.records[q.id].due<=Date.now()).length};}
